<original_code>
import java.io.*;
import java.util.*;

public class Main {
    public static void main(String[] args) throws IOException {
        BufferedReader reader = new BufferedReader(new InputStreamReader(System.in));
        PrintWriter writer = new PrintWriter(System.out);
        int length = Integer.parseInt(reader.readLine());
        String inputLine = reader.readLine();

        boolean inParentheses = false, inWord = false;
        int countWords = 0, currentLength = 0, maxWordLength = 0;

        for (int index = 0; index < length; index++) {
            char ch = inputLine.charAt(index);
            if (inWord && (ch == '_' || ch == '(' || ch == ')' || index == length - 1)) {
                inWord = false;
                if (!(ch == '_' || ch == '(' || ch == ')')) {
                    currentLength++;
                }
                if (inParentheses) {
                    countWords++;
                } else if (currentLength > maxWordLength) {
                    maxWordLength = currentLength;
                }
                if (ch == '(') {
                    inParentheses = true;
                }
                if (ch == ')') {
                    inParentheses = false;
                }
                currentLength = 0;
            } else if (!inWord && !(ch == '_' || ch == '(' || ch == ')')) {
                inWord = true;
                currentLength++;
                if (index == length - 1 && currentLength > maxWordLength) {
                    maxWordLength = currentLength;
                }
            } else if (inWord) {
                currentLength++;
            } else if (ch == '(') {
                inParentheses = true;
            } else if (ch == ')') {
                inParentheses = false;
            }
        }
        writer.printf("%d %d", maxWordLength, countWords);
        writer.close();
    }
}
